export const PT_EDITOR = { en, ru, uk, de, fr, es, ka };

// Label keys of a field of models.js (its `label` names the key when one field name means different things in two
// blocks) and of its options; both editors use these.
// Field labels default to the key; models.js `label` disambiguates keys that mean different things in two blocks.
export const ptFieldLabel = (f) => 'pt.f.' + (f.label || f.key);
export const ptOptionLabel = (f, value) => `pt.o.${f.key}.${value}`;
export const ptFieldHint = (f) => (Object.prototype.hasOwnProperty.call(en, 'pt.fh.' + (f.label || f.key)) ? 'pt.fh.' + (f.label || f.key) : '');
